;
; CASM Phase 10 WP51 listing capture: two conditional VMM stores (a fixed
; 16-byte metadata record per captured physical source line, and a mirror of
; every Pass 2 source-generated byte), plus replay for WP53's later
; serializer. `/L` remains rejected by production orchestration until WP54;
; this module writes no `.LST` file and is never called in production yet.
;
; WP51 increment 3 built allocation (listingCaptureInit), the metadata
; append/replay primitives, and enough lifecycle state (listingStateInit) to
; exercise both in isolation through test_casm_listing.
;
; WP51 increment 4 adds the per-line transaction API (listingBeginLine/
; listingMirrorByte/listingCommitLine), the buffered byte-mirror stage and
; its 65,536-byte endpoint, and listingCaptureFinalize. Emitter/pass/include
; integration -- the real production call sites -- arrives in increment 5.

.include "command64.inc"
.include "common.inc"

.import vmmStoreAlloc
.import vmmWindowRead
.import vmmWindowWrite
.import CasmVmmBuffer
.import sourceSetLineCapture
.import sourceTakeCompletedLine
.import CasmSourceCompletedFlags
.import CasmSourceCompletedStartLo
.import CasmSourceCompletedStartHi
.import CasmSourceCompletedLength
.import CasmSourceCompletedFileId
.import CasmSourceCompletedLineLo
.import CasmSourceCompletedLineHi
.import CasmPc

; WP53 increment 4: the `.LST` file's own I/O. resourceRegisterHandle and
; fileClose (fileio.s) are fully generic already -- neither knows or cares
; whether the handle they manage is the PRG output or the listing file -- so
; the create/close paths below reuse them directly instead of duplicating
; their registry/close logic. CasmListingName/Len (cli.s, WP53 increment 1)
; is this module's only source for the real on-disk name.
.import resourceRegisterHandle
.import fileClose
.import CasmListingName
.import CasmListingLen

.export listingStateInit
.export listingCaptureInit
.export listingMetaAppend
.export listingReplayReset
.export listingReplayNext
.export listingBeginLine
.export listingMirrorByte
.export listingCommitLine
.export listingCaptureFinalize
.export listingFileInit
.export listingCreate
.export listingWrite
.export listingClose
.export listingDelete
.export listingAbort
.export CasmListFileHandle
.export CasmListFileSlot
.export CasmListFileState
.export CasmListFileOpened
.export CasmListFileValid
.export CasmListFileCommitted
.export CasmListFileDeletePending
.export CasmListingOpenName
.export CasmListingState
.export CasmListingMetaVmmSlot
.export CasmListingByteVmmSlot
.export CasmListingRecordCountLo
.export CasmListingRecordCountHi
.export CasmListingPendingFileId
.export CasmListingPendingFlags
.export CasmListingPendingLineLo
.export CasmListingPendingLineHi
.export CasmListingPendingOffsetLo
.export CasmListingPendingOffsetHi
.export CasmListingPendingLen
.export CasmListingPendingPcLo
.export CasmListingPendingPcHi
.export CasmListingPendingByteOffLo
.export CasmListingPendingByteOffHi
.export CasmListingPendingByteCountLo
.export CasmListingPendingByteCountHi
.export CasmListingByteCursorLo
.export CasmListingByteCursorHi
.export CasmListingByteFull
.export CasmListingStage
.export CasmListingStageLen
.export CasmListingTxnActive

.segment "BSS"

CasmListingState:         .res 1
CasmListingMetaVmmSlot:   .res 1
CasmListingByteVmmSlot:   .res 1
CasmListingRecordCountLo: .res 1
CasmListingRecordCountHi: .res 1
CasmListingReplayIndexLo: .res 1
CasmListingReplayIndexHi: .res 1

; WP53 increment 4: the `.LST` file's own I/O lifecycle -- see
; CASM_LISTFILE_*'s own header comment (common.inc) for why this is a
; separate state block from CasmListingState above. CasmListFilePrimary/
; CasmListRequestLo/Hi are private scratch, not exported: mirrors
; fileio.s's own CasmFilePrimary/CasmRequestLo/Hi precedent exactly (a
; caller-invisible detail of listingAbort's primary-diagnostic preservation
; and listingWrite's short-write detection, respectively).
CasmListFileHandle:        .res 1
CasmListFileSlot:          .res 1
CasmListFileState:         .res 1
CasmListFileOpened:        .res 1
CasmListFileValid:         .res 1
CasmListFileCommitted:     .res 1
CasmListFileDeletePending: .res 1
CasmListFilePrimary:       .res 1
CasmListRequestLo:         .res 1
CasmListRequestHi:         .res 1
CasmListingOpenName:       .res CASM_LISTING_OPEN_NAME_SIZE

; WP51 increment 4: byte-mirror endpoint and buffered flush stage.
; CasmListingByteCursorLo/Hi is the next free offset in the byte-mirror VMM
; store while CasmListingByteFull is zero. The exact 65,536th byte write
; advances the cursor from $FFFF and wraps it to $0000 (plain 16-bit
; increment overflow); that wrap is the only signal CasmListingByteFull is
; set from, since the store's own capacity is exactly 65,536 bytes and no
; 17th bit exists to count it directly. CasmListingStage/StageLen buffer up
; to CASM_LISTING_STAGE_SIZE (64) bytes before one vmmWindowWrite flush;
; byte-at-a-time VMM calls are prohibited by the WP51 plan.
CasmListingByteCursorLo:  .res 1
CasmListingByteCursorHi:  .res 1
CasmListingByteFull:      .res 1
CasmListingStage:         .res CASM_LISTING_STAGE_SIZE
CasmListingStageLen:      .res 1

; WP51 increment 4: one-line-at-a-time capture transaction. Snapshotted by
; listingBeginLine, consumed by listingCommitLine. CasmListingTxnFullFlag
; is CasmListingByteFull's value at the transaction's own start -- distinct
; from CasmListingByteFull's live value, since listingCommitLine's byte-
; delta arithmetic must tell "this transaction never wrapped the store" (a
; plain 16-bit subtraction) apart from "this transaction is exactly what
; wrapped the store to zero and set full" (a 16-bit negate) -- CasmListingByteFull
; alone cannot distinguish the two once set.
CasmListingTxnActive:       .res 1
CasmListingTxnPcLo:         .res 1
CasmListingTxnPcHi:         .res 1
CasmListingTxnByteCursorLo: .res 1
CasmListingTxnByteCursorHi: .res 1
CasmListingTxnFullFlag:     .res 1

; Metadata record fields, staged by the caller before listingMetaAppend.
; Reserved0/Reserved1 are not staged here at all -- listingMetaAppend always
; zero-fills the whole 16-byte record first, so reserved bytes are always
; zero regardless of whatever a prior append left in CasmVmmBuffer.
CasmListingPendingFileId:      .res 1
CasmListingPendingFlags:       .res 1
CasmListingPendingLineLo:      .res 1
CasmListingPendingLineHi:      .res 1
CasmListingPendingOffsetLo:    .res 1
CasmListingPendingOffsetHi:    .res 1
CasmListingPendingLen:         .res 1
CasmListingPendingPcLo:        .res 1
CasmListingPendingPcHi:        .res 1
CasmListingPendingByteOffLo:   .res 1
CasmListingPendingByteOffHi:   .res 1
CasmListingPendingByteCountLo: .res 1
CasmListingPendingByteCountHi: .res 1

.segment "CODE"

; ---------------------------------------------------------------------------
; listingStateInit
; Clear listing state to NONE without acquiring any resource: slots'-worth
; of bookkeeping (record/replay counters), the byte-mirror cursor/full flag/
; stage length, and the transaction-active flag. Safe to call unconditionally
; from normal CASM initialization so every listing hook stays a deterministic
; no-op while `/L` is rejected in production.
;
; Explicit, not assumed: BSS is not zero-filled between two loads of the same
; PRG (a "type = bss" segment contributes no bytes to the file at all, so
; nothing ever re-zeroes it at runtime) -- a repeat invocation in the same
; session, such as this module's own test harness calling listingCaptureInit
; many times across its fixtures, would otherwise inherit whatever an earlier
; run or fixture left behind.
;
; Inputs:    none
; Outputs:   A = CASM_DIAG_NONE, C clear
; Clobbers:  A
; ---------------------------------------------------------------------------
listingStateInit:
    lda #CASM_LISTING_STATE_NONE
    sta CasmListingState
    lda #0
    sta CasmListingRecordCountLo
    sta CasmListingRecordCountHi
    sta CasmListingReplayIndexLo
    sta CasmListingReplayIndexHi
    sta CasmListingByteCursorLo
    sta CasmListingByteCursorHi
    sta CasmListingByteFull
    sta CasmListingStageLen
    sta CasmListingTxnActive
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingCaptureInit
; Allocate both listing VMM stores (65,535 bytes requested each; vmmStoreAlloc
; rounds each up to a granted 65,536-byte, 16-page allocation) and enable
; source-side line capture. Requires CasmListingState == NONE (a fresh
; listingStateInit, not yet initialized for capture).
;
; A second-allocation failure leaves the first store's registry slot
; untouched: central cleanup (resources.s's registry sweep) owns releasing
; it, matching the symbol table's and relocation table's own established
; precedent of never freeing a VMM allocation explicitly outside that sweep.
;
; Inputs:    CasmListingState == CASM_LISTING_STATE_NONE
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; both slots recorded;
;            record/replay counters zeroed; source capture enabled;
;            CasmListingState = CASM_LISTING_STATE_ENABLED
;            Failure: A = CASM_DIAG_STREAM_STATE_FAILED (wrong starting
;            state) or an existing VMM diagnostic (CASM_DIAG_VMM_UNAVAILABLE/
;            CASM_DIAG_VMM_ALLOC_FAILED) propagated from vmmStoreAlloc,
;            C set; CasmListingState unchanged
; Clobbers:  A, X, Y, CasmValue0Lo/Hi (via vmmStoreAlloc)
; ---------------------------------------------------------------------------
listingCaptureInit:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_NONE
    beq lciStateOk
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts
lciStateOk:
    ldx #<$FFFF
    ldy #>$FFFF
    jsr vmmStoreAlloc
    bcs lciRet
    stx CasmListingMetaVmmSlot

    ldx #<$FFFF
    ldy #>$FFFF
    jsr vmmStoreAlloc
    bcs lciRet
    stx CasmListingByteVmmSlot

    lda #0
    sta CasmListingRecordCountLo
    sta CasmListingRecordCountHi
    sta CasmListingReplayIndexLo
    sta CasmListingReplayIndexHi

    lda #1
    jsr sourceSetLineCapture

    lda #CASM_LISTING_STATE_ENABLED
    sta CasmListingState
    lda #CASM_DIAG_NONE
    clc
lciRet:
    rts

; ---------------------------------------------------------------------------
; listingMetaAppend
; Append one 16-byte metadata record from the CasmListingPending* staging
; fields. Zero-fills the record first, so Reserved0/Reserved1 are always
; zero regardless of any prior append's leftover CasmVmmBuffer content.
;
; Inputs:    CasmListingPendingFileId/Flags/LineLo/Hi/OffsetLo/Hi/Len/PcLo/Hi/
;            ByteOffLo/Hi/ByteCountLo/Hi staged by the caller
; Outputs:   Success: C clear; record written at index
;            CasmListingRecordCountLo/Hi (before increment), count
;            incremented
;            Failure: A = CASM_DIAG_LISTING_RECORDS_FULL (count already at
;            CASM_LISTING_META_MAX) or CASM_DIAG_VMM_TRANSFER_FAILED, C set;
;            count unchanged
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingMetaAppend:
    lda CasmListingRecordCountHi
    cmp #>CASM_LISTING_META_MAX
    bne lmaNotFull
    lda CasmListingRecordCountLo
    cmp #<CASM_LISTING_META_MAX
    bne lmaNotFull
    lda #CASM_DIAG_LISTING_RECORDS_FULL
    sec
    rts
lmaNotFull:
    ldy #CASM_LISTING_META_REC_SIZE - 1
    lda #0
lmaZeroLoop:
    sta CasmVmmBuffer, y
    dey
    bpl lmaZeroLoop

    lda CasmListingPendingFileId
    sta CasmVmmBuffer + CASM_LISTING_META_FILEID
    lda CasmListingPendingFlags
    sta CasmVmmBuffer + CASM_LISTING_META_FLAGS
    lda CasmListingPendingLineLo
    sta CasmVmmBuffer + CASM_LISTING_META_LINE_LO
    lda CasmListingPendingLineHi
    sta CasmVmmBuffer + CASM_LISTING_META_LINE_HI
    lda CasmListingPendingOffsetLo
    sta CasmVmmBuffer + CASM_LISTING_META_OFF_LO
    lda CasmListingPendingOffsetHi
    sta CasmVmmBuffer + CASM_LISTING_META_OFF_HI
    lda CasmListingPendingLen
    sta CasmVmmBuffer + CASM_LISTING_META_LEN
    lda CasmListingPendingPcLo
    sta CasmVmmBuffer + CASM_LISTING_META_PC_LO
    lda CasmListingPendingPcHi
    sta CasmVmmBuffer + CASM_LISTING_META_PC_HI
    lda CasmListingPendingByteOffLo
    sta CasmVmmBuffer + CASM_LISTING_META_BYTEOFF_LO
    lda CasmListingPendingByteOffHi
    sta CasmVmmBuffer + CASM_LISTING_META_BYTEOFF_HI
    lda CasmListingPendingByteCountLo
    sta CasmVmmBuffer + CASM_LISTING_META_BYTECOUNT_LO
    lda CasmListingPendingByteCountHi
    sta CasmVmmBuffer + CASM_LISTING_META_BYTECOUNT_HI

    ; VMM offset = record index * 16 (16-bit left shift by 4).
    lda CasmListingRecordCountLo
    sta CasmVmmOffLo
    lda CasmListingRecordCountHi
    sta CasmVmmOffHi
    ldx #4
lmaShift:
    asl CasmVmmOffLo
    rol CasmVmmOffHi
    dex
    bne lmaShift

    lda #CASM_LISTING_META_REC_SIZE
    sta CasmIoLenLo
    lda #0
    sta CasmIoLenHi
    ldx CasmListingMetaVmmSlot
    jsr vmmWindowWrite
    bcs lmaRet

    inc CasmListingRecordCountLo
    bne lmaDone
    inc CasmListingRecordCountHi
lmaDone:
    clc
lmaRet:
    rts

; ---------------------------------------------------------------------------
; listingReplayReset
; Reset the metadata replay cursor to the first record. Requires complete
; capture (CasmListingState == COMPLETE) -- WP53's serializer replays only
; after Pass 2 agreement and PRG finalization succeed.
;
; Inputs:    CasmListingState == CASM_LISTING_STATE_COMPLETE
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; replay cursor = 0
;            Failure: A = CASM_DIAG_STREAM_STATE_FAILED, C set
; Clobbers:  A
; ---------------------------------------------------------------------------
listingReplayReset:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_COMPLETE
    beq lrrOk
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts
lrrOk:
    lda #0
    sta CasmListingReplayIndexLo
    sta CasmListingReplayIndexHi
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingReplayNext
; Read one metadata record into CasmVmmBuffer and advance the replay cursor.
; Repeat-stable at EOF: calling again after CASM_STREAM_EOF returns
; CASM_STREAM_EOF again, with no further transfer and the cursor unchanged.
;
; Inputs:    listingReplayReset already called at least once
; Outputs:   Data: A = CASM_STREAM_DATA, C clear; CasmVmmBuffer holds the
;            16-byte record at the pre-advance cursor position; cursor
;            advanced by one record
;            EOF: A = CASM_STREAM_EOF, C clear; cursor unchanged
;            Fail: A = CASM_DIAG_VMM_TRANSFER_FAILED, C set; cursor unchanged
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingReplayNext:
    lda CasmListingReplayIndexLo
    cmp CasmListingRecordCountLo
    lda CasmListingReplayIndexHi
    sbc CasmListingRecordCountHi
    bcc lrnHaveRecord            ; replay index < record count
    lda #CASM_STREAM_EOF
    clc
    rts
lrnHaveRecord:
    lda CasmListingReplayIndexLo
    sta CasmVmmOffLo
    lda CasmListingReplayIndexHi
    sta CasmVmmOffHi
    ldx #4
lrnShift:
    asl CasmVmmOffLo
    rol CasmVmmOffHi
    dex
    bne lrnShift

    lda #CASM_LISTING_META_REC_SIZE
    sta CasmIoLenLo
    lda #0
    sta CasmIoLenHi
    ldx CasmListingMetaVmmSlot
    jsr vmmWindowRead
    bcs lrnFail

    inc CasmListingReplayIndexLo
    bne lrnDone
    inc CasmListingReplayIndexHi
lrnDone:
    lda #CASM_STREAM_DATA
    clc
    rts
lrnFail:
    lda #CASM_DIAG_VMM_TRANSFER_FAILED
    sec
    rts

; ---------------------------------------------------------------------------
; listingFlushStage (private, WP51 increment 4)
; Flush CasmListingStage[0..CasmListingStageLen-1] to the byte-mirror VMM
; store at offset = CasmListingByteCursorLo/Hi - CasmListingStageLen, then
; clear CasmListingStageLen only after a successful write. A store that
; just became exactly full always flushes on a stage boundary: 65,536 is an
; exact multiple of CASM_LISTING_STAGE_SIZE (64), so the destination
; computed here for a just-wrapped cursor (0 - StageLen, a 16-bit borrow)
; correctly lands on the store's final 64-byte page.
;
; Inputs:    CasmListingStage/StageLen, CasmListingByteCursorLo/Hi
; Outputs:   Success: C clear; StageLen cleared (or was already 0: a no-op)
;            Failure: A = CASM_DIAG_VMM_TRANSFER_FAILED, C set; StageLen
;            unchanged
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingFlushStage:
    lda CasmListingStageLen
    beq lfsNothing

    lda CasmListingByteCursorLo
    sec
    sbc CasmListingStageLen
    sta CasmVmmOffLo
    lda CasmListingByteCursorHi
    sbc #0
    sta CasmVmmOffHi

    ldy CasmListingStageLen
    dey
lfsCopyLoop:
    lda CasmListingStage, y
    sta CasmVmmBuffer, y
    dey
    bpl lfsCopyLoop

    lda CasmListingStageLen
    sta CasmIoLenLo
    lda #0
    sta CasmIoLenHi
    ldx CasmListingByteVmmSlot
    jsr vmmWindowWrite
    bcs lfsFail

    lda #0
    sta CasmListingStageLen
lfsNothing:
    clc
    rts
lfsFail:
    rts

; ---------------------------------------------------------------------------
; listingBeginLine (WP51 increment 4)
; Begin one capture transaction: snapshot the current PC, byte-mirror
; cursor, and full flag, then mark the transaction active. No-op when
; capture is disabled. A duplicate begin (a transaction already active)
; means a prior line was never committed -- a caller ordering defect, not a
; reachable condition through correct emitter/pass integration.
;
; Inputs:    CasmPc (emit.s)
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; transaction active
;            Failure: A = CASM_DIAG_LISTING_REPLAY_MISMATCH, C set (a
;            transaction was already active); nothing changed
;            Disabled: C clear; no-op
; Clobbers:  A
; ---------------------------------------------------------------------------
listingBeginLine:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_ENABLED
    beq lblEnabled
    clc
    rts
lblEnabled:
    lda CasmListingTxnActive
    beq lblNoTxn
    lda #CASM_DIAG_LISTING_REPLAY_MISMATCH
    sec
    rts
lblNoTxn:
    lda CasmPc
    sta CasmListingTxnPcLo
    lda CasmPc + 1
    sta CasmListingTxnPcHi
    lda CasmListingByteCursorLo
    sta CasmListingTxnByteCursorLo
    lda CasmListingByteCursorHi
    sta CasmListingTxnByteCursorHi
    lda CasmListingByteFull
    sta CasmListingTxnFullFlag
    lda #1
    sta CasmListingTxnActive
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingMirrorByte (WP51 increment 4)
; Mirror one Pass 2 source-generated byte. No-op when capture is disabled.
; Requires an active transaction. Rejects before any mutation once the
; store is already full. Appends to the buffered stage, advances the
; 16-bit byte cursor, flushes the stage whenever it reaches
; CASM_LISTING_STAGE_SIZE bytes, and detects the exact 65,536-byte wrap.
;
; Inputs:    A = the byte to mirror
; Outputs:   Success: C clear; byte staged (and flushed if the stage just
;            filled); cursor advanced; CasmListingByteFull set if this byte
;            was exactly the store's 65,536th
;            Failure: A = CASM_DIAG_LISTING_REPLAY_MISMATCH (no active
;            transaction), CASM_DIAG_LISTING_BYTES_FULL (store already
;            full), or CASM_DIAG_VMM_TRANSFER_FAILED (stage flush failed),
;            C set
;            Disabled: C clear; no-op
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingMirrorByte:
    pha
    lda CasmListingState
    cmp #CASM_LISTING_STATE_ENABLED
    beq lmbEnabled
    pla
    clc
    rts
lmbEnabled:
    lda CasmListingTxnActive
    bne lmbHaveTxn
    pla
    lda #CASM_DIAG_LISTING_REPLAY_MISMATCH
    sec
    rts
lmbHaveTxn:
    lda CasmListingByteFull
    beq lmbNotFull
    pla
    lda #CASM_DIAG_LISTING_BYTES_FULL
    sec
    rts
lmbNotFull:
    pla
    ldy CasmListingStageLen
    sta CasmListingStage, y
    inc CasmListingStageLen

    inc CasmListingByteCursorLo
    bne lmbCursorDone
    inc CasmListingByteCursorHi
lmbCursorDone:
    lda CasmListingByteCursorLo
    ora CasmListingByteCursorHi
    bne lmbNotWrapped
    lda #1
    sta CasmListingByteFull      ; cursor wrapped to exactly 0 -> store full
lmbNotWrapped:

    lda CasmListingStageLen
    cmp #CASM_LISTING_STAGE_SIZE
    bne lmbDone
    jsr listingFlushStage
    bcs lmbRet
lmbDone:
    clc
lmbRet:
    rts

; ---------------------------------------------------------------------------
; listingCommitLine (WP51 increment 4)
; End the active capture transaction. No-op when capture is disabled.
; Consumes the completed-line sidecar (sourceTakeCompletedLine): no pending
; completion, or a synthetic-only one, clears the transaction with no
; metadata record. A real physical line computes the emitted-byte delta
; since listingBeginLine (handling the exact-full wraparound), translates
; the sidecar's FINAL_UNTERMINATED bit into the metadata record's own
; single-bit Flags encoding, stages every field, and appends one record.
;
; Inputs:    an active transaction (listingBeginLine already called)
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; transaction cleared;
;            zero or one metadata record appended
;            Failure: A = CASM_DIAG_LISTING_REPLAY_MISMATCH (no active
;            transaction), CASM_DIAG_LISTING_RECORDS_FULL, or
;            CASM_DIAG_VMM_TRANSFER_FAILED, C set; transaction cleared
;            regardless (a stalled transaction must never block whatever
;            fatal-abort path the caller takes next)
;            Disabled: C clear; no-op
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingCommitLine:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_ENABLED
    beq lclEnabled
    clc
    rts
lclEnabled:
    lda CasmListingTxnActive
    bne lclHaveTxn
    lda #CASM_DIAG_LISTING_REPLAY_MISMATCH
    sec
    rts
lclHaveTxn:
    jsr sourceTakeCompletedLine
    ; sourceTakeCompletedLine already cleared VALID in CasmSourceCompletedFlags
    ; itself as part of consuming it -- the returned A is the only place the
    ; pre-consume flags still exist, so stash it now rather than re-reading
    ; the module variable for the SYNTHETIC_ONLY/FINAL_UNTERMINATED checks
    ; below (into CasmListingPendingFlags, overwritten with the translated
    ; single-bit value once those checks are done).
    sta CasmListingPendingFlags
    and #CASM_SOURCE_COMPLETED_FLAG_VALID
    bne lclHavePending
    jmp lclClearNoRecord
lclHavePending:
    lda CasmListingPendingFlags
    and #CASM_SOURCE_COMPLETED_FLAG_SYNTHETIC_ONLY
    beq lclRealLine
    jmp lclClearNoRecord
lclRealLine:

    ; Translate the sidecar's FINAL_UNTERMINATED bit into the metadata
    ; record's own bit 0 -- the two encodings are deliberately different
    ; bytes (the sidecar carries VALID/SYNTHETIC_ONLY too; the metadata
    ; record's Flags field never does).
    lda CasmListingPendingFlags
    and #CASM_SOURCE_COMPLETED_FLAG_FINAL_UNTERMINATED
    beq lclFlagsNotFinal
    lda #CASM_LISTING_META_FLAG_FINAL_UNTERMINATED
    jmp lclFlagsReady
lclFlagsNotFinal:
    lda #0
lclFlagsReady:
    sta CasmListingPendingFlags

    lda CasmSourceCompletedFileId
    sta CasmListingPendingFileId
    lda CasmSourceCompletedLineLo
    sta CasmListingPendingLineLo
    lda CasmSourceCompletedLineHi
    sta CasmListingPendingLineHi
    lda CasmSourceCompletedStartLo
    sta CasmListingPendingOffsetLo
    lda CasmSourceCompletedStartHi
    sta CasmListingPendingOffsetHi
    lda CasmSourceCompletedLength
    sta CasmListingPendingLen

    lda CasmListingTxnPcLo
    sta CasmListingPendingPcLo
    lda CasmListingTxnPcHi
    sta CasmListingPendingPcHi
    lda CasmListingTxnByteCursorLo
    sta CasmListingPendingByteOffLo
    lda CasmListingTxnByteCursorHi
    sta CasmListingPendingByteOffHi

    ; Byte delta since listingBeginLine. A transaction that began already
    ; full accepted no bytes (listingMirrorByte rejects before mutation),
    ; so the plain-subtract path below already yields 0 in that case (the
    ; cursor cannot have moved). Only a transaction that was NOT full at
    ; begin but IS full now just wrapped the cursor to exactly 0, requiring
    ; the 16-bit negate instead of a plain subtract.
    lda CasmListingTxnFullFlag
    bne lclNoWrap
    lda CasmListingByteFull
    beq lclNoWrap
    lda #0
    sec
    sbc CasmListingTxnByteCursorLo
    sta CasmListingPendingByteCountLo
    lda #0
    sbc CasmListingTxnByteCursorHi
    sta CasmListingPendingByteCountHi
    jmp lclDeltaReady
lclNoWrap:
    lda CasmListingByteCursorLo
    sec
    sbc CasmListingTxnByteCursorLo
    sta CasmListingPendingByteCountLo
    lda CasmListingByteCursorHi
    sbc CasmListingTxnByteCursorHi
    sta CasmListingPendingByteCountHi
lclDeltaReady:

    jsr listingMetaAppend
    bcc lclClearOk
    pha
    lda #0
    sta CasmListingTxnActive
    pla
    sec
    rts
lclClearOk:
    lda #0
    sta CasmListingTxnActive
    lda #CASM_DIAG_NONE
    clc
    rts
lclClearNoRecord:
    lda #0
    sta CasmListingTxnActive
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingCaptureFinalize (WP51 increment 4)
; Close listing capture after Pass 2 completes. Requires enabled capture,
; no active transaction, and no unconsumed sidecar (peeked directly via
; CasmSourceCompletedFlags, not consumed -- only sourceTakeCompletedLine
; ever clears it). Flushes any final partial byte-mirror stage, disables
; source-side capture, and marks capture complete. Both VMM allocations stay
; live for WP53's later serializer; this routine never frees either.
;
; Inputs:    CasmListingState == CASM_LISTING_STATE_ENABLED
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; CasmListingState =
;            CASM_LISTING_STATE_COMPLETE; source capture disabled
;            Failure: A = CASM_DIAG_STREAM_STATE_FAILED (wrong starting
;            state), CASM_DIAG_LISTING_REPLAY_MISMATCH (active transaction
;            or unconsumed sidecar), or CASM_DIAG_VMM_TRANSFER_FAILED
;            (final stage flush failed), C set; CasmListingState unchanged
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingCaptureFinalize:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_ENABLED
    beq lcfEnabled
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts
lcfEnabled:
    lda CasmListingTxnActive
    beq lcfNoTxn
    lda #CASM_DIAG_LISTING_REPLAY_MISMATCH
    sec
    rts
lcfNoTxn:
    lda CasmSourceCompletedFlags
    and #CASM_SOURCE_COMPLETED_FLAG_VALID
    beq lcfNoSidecar
    lda #CASM_DIAG_LISTING_REPLAY_MISMATCH
    sec
    rts
lcfNoSidecar:
    jsr listingFlushStage
    bcs lcfRet
    lda #0
    jsr sourceSetLineCapture
    lda #CASM_LISTING_STATE_COMPLETE
    sta CasmListingState
    lda #CASM_DIAG_NONE
    clc
lcfRet:
    rts

; =============================================================================
; WP53 increment 4: `.LST` file ownership and I/O
;
; Everything below is dedicated to the real on-disk listing file: creating
; it (with CBM DOS's native replace-on-open behavior), writing to it,
; closing it, deleting it, and a best-effort abort. All five map directly to
; CASM_DIAG_LISTING_CREATE_FAILED/WRITE_FAILED/CLOSE_FAILED/DELETE_FAILED/
; SHORT_WRITE ($3D-$41). WP53 links every routine here but adds no
; production call site -- `/L` stays rejected until WP54, which also owns
; calling listingCreate/listingWrite/listingClose/outputCommit in the real
; Pass 2 tail, in the plan's own required order (PRG committed before any
; listing write).
; =============================================================================

; ---------------------------------------------------------------------------
; listingFileInit (WP53)
; Initialize all `.LST` file I/O state to closed/none. Does not touch
; CasmListingState or any WP51 capture field -- a wholly separate lifecycle,
; see CASM_LISTFILE_*'s own header comment (common.inc).
;
; Inputs:    none
; Outputs:   A = CASM_DIAG_NONE, C clear, Z set
; Preserves: X, Y
; Clobbers:  A, processor flags
; ---------------------------------------------------------------------------
listingFileInit:
    lda #CASM_INVALID_HANDLE
    sta CasmListFileHandle
    lda #CASM_INVALID_SLOT
    sta CasmListFileSlot
    lda #CASM_FILE_STATE_CLOSED
    sta CasmListFileState
    lda #0
    sta CasmListFileOpened
    sta CasmListFileValid
    sta CasmListFileCommitted
    sta CasmListFileDeletePending
    sta CasmListRequestLo
    sta CasmListRequestHi
    sta CasmListFilePrimary
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingBuildOpenName (private, WP53)
; Build CasmListingOpenName from CasmListingName with CBM DOS's native
; "@0:" replace marker inserted immediately after a device-prefix colon, or
; prepended if CasmListingName has none -- WP50's frozen file-ownership
; resolution: "<device-digits>:@0:<basename>.LST" or "@0:<basename>.LST".
; No existence probe and no create-vs-replace branch: the drive itself
; replaces an existing same-name file transparently, the same behavior
; test_casm_listwrite proves through the real OS/VICE path.
;
; A CasmListingName can contain at most one colon (cliDeriveListingName only
; ever copies a colon from a source name's own leading device prefix, the
; sole position that grammar allows), so the first colon found, if any, is
; unambiguously the device prefix -- no scan-to-last-colon logic is needed
; here, unlike cliDeriveOutputName/cliDeriveListingName's own dot scans.
;
; Inputs:    CasmListingName/CasmListingLen already derived (WP53
;            increment 1)
; Outputs:   CasmListingOpenName holds the null-terminated open name
; Preserves: none
; Clobbers:  A, X, Y
; ---------------------------------------------------------------------------
listingBuildOpenName:
    ldx #0
lbonScan:
    cpx CasmListingLen
    beq lbonNoColon
    lda CasmListingName, x
    cmp #CASM_PETSCII_COLON
    beq lbonFoundColon
    inx
    jmp lbonScan
lbonFoundColon:
    inx                           ; X = index right after the colon
    jmp lbonCopyHead
lbonNoColon:
    ldx #0
lbonCopyHead:
    ; Copy CasmListingName[0..X-1] verbatim into CasmListingOpenName[0..X-1].
    stx CasmListRequestLo          ; stash split point
    ldy #0
lbonHeadLoop:
    cpy CasmListRequestLo
    beq lbonMarker
    lda CasmListingName, y
    sta CasmListingOpenName, y
    iny
    jmp lbonHeadLoop
lbonMarker:
    ; Y == CasmListRequestLo here; write '@','0',':' at that offset.
    lda #CASM_PETSCII_AT
    sta CasmListingOpenName, y
    iny
    lda #CASM_PETSCII_DIGIT_0
    sta CasmListingOpenName, y
    iny
    lda #CASM_PETSCII_COLON
    sta CasmListingOpenName, y
    iny
    ; Copy the remainder of CasmListingName[X..] (including its null) from
    ; CasmListRequestLo onward into CasmListingOpenName starting at Y.
    ldx CasmListRequestLo
lbonTailLoop:
    lda CasmListingName, x
    sta CasmListingOpenName, y
    beq lbonDone
    inx
    iny
    jmp lbonTailLoop
lbonDone:
    rts

; ---------------------------------------------------------------------------
; listingCreate (WP53)
; Create (or transparently replace) the real `.LST` file and register its
; handle. Listing type is SEQ, always write mode.
;
; Inputs:    CasmListFileState == CASM_FILE_STATE_CLOSED; CasmListingName/
;            Len already derived
; Outputs:   Success: C clear, A = CASM_DIAG_NONE; CasmListFileHandle/Slot
;                     valid; CasmListFileState = OPEN; Opened/Valid = true
;            Fail:    C set, A = CASM_DIAG_STREAM_STATE_FAILED (bad
;                     precondition state) or CASM_DIAG_LISTING_CREATE_FAILED
;                     (rejected DOS_OPEN_FILE or registration)
; Preserves: none
; Clobbers:  A, X, Y, HexValLo/Hi, FileHandle, OS API volatile state
; Scratch:   CasmValue1Lo
; ---------------------------------------------------------------------------
listingCreate:
    lda CasmListFileState
    cmp #CASM_FILE_STATE_CLOSED
    bne lcrBadState
    jsr listingBuildOpenName
    lda #CASM_FILE_MODE_WRITE
    sta HexValLo
    lda #CASM_PETSCII_S
    sta HexValHi
    ldx #<CasmListingOpenName
    ldy #>CasmListingOpenName
    lda #DOS_OPEN_FILE
    jsr OS_API
    bcs lcrCreateFailed
    sta CasmValue1Lo
    jsr resourceRegisterHandle
    bcs lcrRegistrationFailed
    stx CasmListFileSlot
    lda CasmValue1Lo
    sta CasmListFileHandle
    lda #CASM_FILE_STATE_OPEN
    sta CasmListFileState
    lda #CASM_LISTFILE_OPENED
    sta CasmListFileOpened
    lda #CASM_LISTFILE_VALID
    sta CasmListFileValid
    lda #CASM_DIAG_NONE
    clc
    rts
lcrRegistrationFailed:
    lda CasmValue1Lo
    sta FileHandle
    lda #DOS_CLOSE_FILE
    jsr OS_API
    lda #CASM_DIAG_LISTING_CREATE_FAILED
    sec
    rts
lcrCreateFailed:
    lda #CASM_DIAG_LISTING_CREATE_FAILED
    sec
    rts
lcrBadState:
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts

; ---------------------------------------------------------------------------
; listingWrite (WP53)
; Write one bounded block to the managed listing output and reject short
; writes. Mirrors fileio.s's fileWrite exactly, targeting the listing
; file's own handle/state instead of the PRG output's.
;
; Inputs:    X/Y = source pointer (low/high); CasmIoLenLo/Hi = requested
;            byte count; CasmListFileState == CASM_FILE_STATE_OPEN
; Outputs:   Success: C clear, A = CASM_DIAG_NONE; CasmIoLenLo/Hi = actual
;                     byte count (== requested)
;            Fail:    C set, A = CASM_DIAG_STREAM_STATE_FAILED,
;                     CASM_DIAG_LISTING_WRITE_FAILED, or
;                     CASM_DIAG_LISTING_SHORT_WRITE; the latter two also set
;                     CasmListFileValid = CASM_LISTFILE_INVALID
; Preserves: none
; Clobbers:  A, X, Y, HexValLo/Hi, FileHandle, OS API volatile state
; ---------------------------------------------------------------------------
listingWrite:
    lda CasmListFileState
    cmp #CASM_FILE_STATE_OPEN
    bne lwrBadState
    lda CasmIoLenLo
    sta CasmListRequestLo
    sta HexValLo
    lda CasmIoLenHi
    sta CasmListRequestHi
    sta HexValHi
    lda CasmListFileHandle
    sta FileHandle
    lda #DOS_WRITE_FILE
    jsr OS_API
    php
    lda HexValLo
    sta CasmIoLenLo
    lda HexValHi
    sta CasmIoLenHi
    plp
    bcs lwrWriteFailed
    lda CasmIoLenLo
    cmp CasmListRequestLo
    bne lwrShortWrite
    lda CasmIoLenHi
    cmp CasmListRequestHi
    bne lwrShortWrite
    lda #CASM_DIAG_NONE
    clc
    rts
lwrWriteFailed:
    lda #CASM_LISTFILE_INVALID
    sta CasmListFileValid
    lda #CASM_DIAG_LISTING_WRITE_FAILED
    sec
    rts
lwrShortWrite:
    lda #CASM_LISTFILE_INVALID
    sta CasmListFileValid
    lda #CASM_DIAG_LISTING_SHORT_WRITE
    sec
    rts
lwrBadState:
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts

; ---------------------------------------------------------------------------
; listingClose (WP53)
; Close and release the listing handle through fileio.s's generic fileClose.
; A failed close leaves CasmListFileState == CLOSE_FAILED and the
; handle/slot registered, exactly as fileio.s's own close paths do -- a
; later retry (via a direct call or through listingAbort) attempts the same
; close again since state never reaches CLOSED.
;
; Inputs:    CasmListFileState == CASM_FILE_STATE_OPEN
; Outputs:   Success: C clear, A = CASM_DIAG_NONE; handle/slot released,
;                     state CLOSED
;            Fail:    C set, A = CASM_DIAG_STREAM_STATE_FAILED (bad
;                     precondition state) or CASM_DIAG_LISTING_CLOSE_FAILED
;                     (state becomes CLOSE_FAILED)
; Preserves: none
; Clobbers:  A, X, Y and fileClose clobbers
; ---------------------------------------------------------------------------
listingClose:
    lda CasmListFileState
    cmp #CASM_FILE_STATE_OPEN
    bne lclBadState
    lda CasmListFileHandle
    ldx CasmListFileSlot
    ldy #CASM_DIAG_LISTING_CLOSE_FAILED
    jsr fileClose
    bcs lclFailed
    lda #CASM_INVALID_HANDLE
    sta CasmListFileHandle
    lda #CASM_INVALID_SLOT
    sta CasmListFileSlot
    lda #CASM_FILE_STATE_CLOSED
    sta CasmListFileState
    lda #CASM_DIAG_NONE
    clc
    rts
lclFailed:
    lda #CASM_FILE_STATE_CLOSE_FAILED
    sta CasmListFileState
    lda #CASM_DIAG_LISTING_CLOSE_FAILED
    sec
    rts
lclBadState:
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts

; ---------------------------------------------------------------------------
; listingDelete (WP53)
; Delete CasmListingName (the plain name -- never the "@0:"-embedded open
; name, which exists only to reach DOS_OPEN_FILE) through the native file
; service. A dedicated routine rather than reusing fileio.s's own
; fileDelete: that routine's failure diagnostic is the PRG-output-specific
; CASM_DIAG_OUTPUT_DELETE_FAILED, not the listing-specific $40 WP53's own
; diagnostic contiguity requires.
;
; Inputs:    CasmListingName already derived
; Outputs:   C clear, A = CASM_DIAG_NONE on success
;            C set, A = CASM_DIAG_LISTING_DELETE_FAILED on failure
; Preserves: none
; Clobbers:  A, X, Y, OS API volatile state
; ---------------------------------------------------------------------------
listingDelete:
    ldx #<CasmListingName
    ldy #>CasmListingName
    lda #DOS_DELETE_FILE
    jsr OS_API
    bcs ldlFailed
    lda #CASM_DIAG_NONE
    clc
    rts
ldlFailed:
    lda #CASM_DIAG_LISTING_DELETE_FAILED
    sec
    rts

; ---------------------------------------------------------------------------
; listingAbort (WP53)
; Best-effort close and delete for an incomplete listing file, preserving
; the caller's primary diagnostic -- mirrors fileio.s's outputAbort exactly,
; with one addition: a committed listing (CasmListFileCommitted ==
; CASM_LISTFILE_COMMITTED) is never deleted, regardless of
; CasmListFileOpened. WP53 links this routine but calls it from no
; production site; WP54 owns wiring it into the real failure path.
;
; A failed close returns immediately without attempting delete (state stays
; CLOSE_FAILED, so a repeated call retries the close). A failed delete sets
; CasmListFileDeletePending and leaves CasmListFileOpened true, so a
; repeated call retries the delete; CasmListFileDeletePending itself is
; observability, not load-bearing for that retry -- CasmListFileOpened
; alone already drives it, exactly as CasmOutputCreated alone already
; drives outputAbort's own retry.
;
; Inputs:    A = primary CASM_DIAG_* value, or CASM_DIAG_NONE
; Outputs:   A = preserved primary, or first cleanup diagnostic if none
;            C set when returned A is nonzero, clear otherwise
; Preserves: none
; Clobbers:  A, X, Y and listingClose/listingDelete clobbers
; Scratch:   CasmListFilePrimary
; ---------------------------------------------------------------------------
listingAbort:
    sta CasmListFilePrimary
    lda CasmListFileState
    cmp #CASM_FILE_STATE_CLOSED
    beq laDelete
    jsr listingClose
    bcc laDelete
    ; listingClose already set CasmListFileState/A/C for a close failure.
    jsr laRecordSecondary
    jmp laReturn

laDelete:
    lda CasmListFileCommitted
    bne laReturn                  ; WP53: committed listings are never deleted
    lda CasmListFileOpened
    beq laReturn
    jsr listingDelete
    bcc laDeleteDone
    pha
    lda #CASM_LISTFILE_DELETE_PENDING
    sta CasmListFileDeletePending
    pla
    jsr laRecordSecondary
    jmp laReturn
laDeleteDone:
    lda #CASM_LISTFILE_NOT_OPENED
    sta CasmListFileOpened
    lda #CASM_LISTFILE_DELETE_NOT_PENDING
    sta CasmListFileDeletePending

laReturn:
    lda CasmListFilePrimary
    beq laSuccess
    sec
    rts
laSuccess:
    clc
    rts

; Input: A = secondary diagnostic. Preserve a nonzero primary.
laRecordSecondary:
    pha
    lda CasmListFilePrimary
    bne laKeepPrimary
    pla
    sta CasmListFilePrimary
    rts
laKeepPrimary:
    pla
    rts
